/**
 * Where the on-device model lives. By default it's served from
 * public/models/<id>/ (generated by scripts/export_emotion_model.py). Set
 * NEXT_PUBLIC_EMOTION_MODEL_HOST=hub and NEXT_PUBLIC_EMOTION_MODEL_ID=<user>/<repo>
 * to load it from the Hugging Face Hub instead (recommended for Vercel, since
 * the 83 MB model is better kept out of git).
 */
const host = process.env.NEXT_PUBLIC_EMOTION_MODEL_HOST === "hub" ? "hub" : "local";
const modelId = process.env.NEXT_PUBLIC_EMOTION_MODEL_ID || "sonora-emotion";
const localPath = "/models/";

/** Folder that holds sonora_meta.json, config.json, tokenizer files and onnx/. */
const baseUrl = host === "hub" ? `https://huggingface.co/${modelId}/resolve/main/` : `${localPath}${modelId}/`;

export const MODEL_CONFIG = {
  host,
  modelId,
  localPath,
  baseUrl,
  metaUrl: `${baseUrl}sonora_meta.json`,
  /** Approximate download size, shown before the first load. */
  approxSizeMb: 83,
} as const;
